-- Run after causal_inbox_basic.sql on a fresh fixture in the same connection.
SET ROLE contour_causal_inbox_writer;
DO $$ BEGIN
 -- Existing root a, then delivery naming boundary a as its own activity.
 BEGIN PERFORM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000020',format('{"activity":"%s","event_id":"%s","kind":"delivery","parent":"%s","root":"%s","seq":20}',repeat('a',32),repeat('d',32),repeat('f',32),repeat('a',32)),20)); RAISE EXCEPTION 'delivery boundary alias accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
 -- Existing delivery activity b, then a root naming that boundary.
 BEGIN PERFORM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_payload('dd000000-0000-4000-8000-000000000021',21,repeat('d',32),repeat('b',32))); RAISE EXCEPTION 'root delivery alias accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
 -- Existing boundary a, then attempt claims it under a different root.
 BEGIN PERFORM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000022',format('{"activity":"%s","attempt":"%s","event_id":"%s","kind":"attempt","marker_digest":"%s","root":"%s","seq":22}',repeat('a',32),repeat('e',32),repeat('d',32),repeat('f',64),repeat('c',32)),22)); RAISE EXCEPTION 'attempt boundary cross root accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
END $$;
-- An attempt without a known boundary is admissible, including a repeated tuple.
SELECT * FROM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000023',format('{"activity":"%s","attempt":"%s","event_id":"%s","kind":"attempt","marker_digest":"%s","root":"%s","seq":23}',repeat('c',32),repeat('d',32),repeat('e',32),repeat('f',64),repeat('f',32)),23));
SELECT * FROM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000024',format('{"activity":"%s","attempt":"%s","event_id":"%s","kind":"attempt","marker_digest":"%s","root":"%s","seq":24}',repeat('c',32),repeat('d',32),repeat('f',32),repeat('f',64),repeat('f',32)),24));
DO $$ BEGIN
 -- New boundary contradicts an already observed attempt's root.
 BEGIN PERFORM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_payload('dd000000-0000-4000-8000-000000000025',25,repeat('c',32),repeat('c',32))); RAISE EXCEPTION 'root attempt boundary accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
 BEGIN PERFORM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000026',format('{"activity":"%s","attempt":"%s","event_id":"%s","kind":"attempt","marker_digest":"%s","root":"%s","seq":26}',repeat('c',32),repeat('d',32),repeat('c',32),repeat('e',64),repeat('f',32)),26)); RAISE EXCEPTION 'attempt marker contradiction accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
 BEGIN PERFORM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000027',format('{"activity":"%s","event_id":"%s","kind":"delivery","parent":"%s","root":"%s","seq":27}',repeat('c',32),repeat('c',32),repeat('d',32),repeat('e',32)),27)); RAISE EXCEPTION 'delivery cross root accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
END $$;
RESET ROLE;
SET ROLE contour_causal_inbox_writer;
-- Reverse marker order: lower digest arrives first on a different attempt ID.
SELECT * FROM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000028',format('{"activity":"%s","attempt":"%s","event_id":"%s","kind":"attempt","marker_digest":"%s","root":"%s","seq":28}',repeat('c',32),repeat('3',32),repeat('6',32),repeat('e',64),repeat('f',32)),28));
DO $$ BEGIN
 BEGIN PERFORM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000029',format('{"activity":"%s","attempt":"%s","event_id":"%s","kind":"attempt","marker_digest":"%s","root":"%s","seq":29}',repeat('c',32),repeat('3',32),repeat('7',32),repeat('f',64),repeat('f',32)),29)); RAISE EXCEPTION 'reverse attempt contradiction accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
END $$;
-- Matching delivery tuples can repeat; changing their parent cannot.
SELECT * FROM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000030',format('{"activity":"%s","event_id":"%s","kind":"delivery","parent":"%s","root":"%s","seq":30}',repeat('c',32),repeat('7',32),repeat('d',32),repeat('f',32)),30));
SELECT * FROM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000031',format('{"activity":"%s","event_id":"%s","kind":"delivery","parent":"%s","root":"%s","seq":31}',repeat('c',32),repeat('8',32),repeat('d',32),repeat('f',32)),31));
DO $$ BEGIN
 BEGIN PERFORM contour.accept_causal_batch('f0000000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',1,decode(repeat('33',32),'hex'),decode(repeat('ab',32),'hex'),pg_temp.inbox_event('dd000000-0000-4000-8000-000000000032',format('{"activity":"%s","event_id":"%s","kind":"delivery","parent":"%s","root":"%s","seq":32}',repeat('c',32),repeat('9',32),repeat('e',32),repeat('f',32)),32)); RAISE EXCEPTION 'conflicting parent accepted'; EXCEPTION WHEN unique_violation THEN NULL; END;
END $$;
RESET ROLE;
